// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzBlockNumber) public {
        vm.assume(fuzzBlockNumber % 15 == 0);
        vm.roll(fuzzBlockNumber);
        vm.warp(1);

        address sender = address(0x1234);
        vm.deal(sender, 100 ether);

        vm.prank(sender);
        (bool s1,) = address(c).call{value: 10 ether}("");
        require(s1, "first call failed");

        vm.warp(block.timestamp + 2);

        uint256 senderBalanceBefore = address(sender).balance;

        vm.prank(sender);
        (bool s2,) = address(c).call{value: 10 ether}("");
        require(s2, "second call failed");

        assertTrue(address(c).balance == 0);
    }
}
